"""Tarea 0.4/0.8 — las migraciones están aplicadas y coinciden con los modelos."""

from __future__ import annotations

from alembic import command
from alembic.runtime.migration import MigrationContext
from alembic.script import ScriptDirectory

from app.infra.db import get_engine
from tests.api.conftest import alembic_config


def test_alembic_check_no_reporta_diferencias() -> None:
    # Lanza alembic.util.exc.AutogenerateDiffsDetected si los modelos y la BD no coinciden.
    command.check(alembic_config())


def test_la_bd_esta_en_la_ultima_revision() -> None:
    script = ScriptDirectory.from_config(alembic_config())
    with get_engine().connect() as conn:
        current = MigrationContext.configure(conn).get_current_heads()

    assert set(current) == set(script.get_heads())


def test_alembic_usa_la_url_de_la_configuracion(test_database: str) -> None:
    # env.py debe tomar la URL de get_settings(), no de un valor fijo en alembic.ini.
    assert get_engine().url.render_as_string(hide_password=False) == test_database
